// Do not edit this file as it will be overwritten if HAMR codegen is rerun

//! The GUMBO contract checks of every thread: IEP_Post at initialization, CEP_Pre
//! when a thread is about to be dispatched, and CEP_Post when it completes, against
//! the pre-state saved at dispatch.

use data::*;
use crate::{Event, SystemView, ViolationSink};
use crate::gumbox::temp_sensor_temp_sensor_containers::*;
use crate::gumbox::operator_interface_operator_interface_containers::*;
use crate::gumbox::thermostat_thermostat_containers::*;
use crate::gumbox::heat_source_heat_source_containers::*;

pub struct ComponentContracts {
  pre_temp_sensor_temp_sensor: Option<PreState_temp_sensor_temp_sensor>,
  pre_ok_temp_sensor_temp_sensor: bool,
  pre_operator_interface_operator_interface: Option<PreState_operator_interface_operator_interface>,
  pre_ok_operator_interface_operator_interface: bool,
  pre_thermostat_thermostat: Option<PreState_thermostat_thermostat>,
  pre_ok_thermostat_thermostat: bool,
  pre_heat_source_heat_source: Option<PreState_heat_source_heat_source>,
  pre_ok_heat_source_heat_source: bool,
}

impl ComponentContracts {
  pub const fn new() -> Self {
    ComponentContracts {
      pre_temp_sensor_temp_sensor: None,
      pre_ok_temp_sensor_temp_sensor: true,
      pre_operator_interface_operator_interface: None,
      pre_ok_operator_interface_operator_interface: true,
      pre_thermostat_thermostat: None,
      pre_ok_thermostat_thermostat: true,
      pre_heat_source_heat_source: None,
      pre_ok_heat_source_heat_source: true,
    }
  }

  /// Initialization guarantees, checked once every thread has initialized and
  /// before any has computed.
  pub fn on_init<V: SystemView, S: ViolationSink>(&mut self, s: &mut V, out: &mut S) {
    {
      s.focus(Some(crate::Thread::temp_sensor_temp_sensor));
      let post_temp_sensor_temp_sensor = PostState_temp_sensor_temp_sensor {
        api_temp_changed: s.get_temp_sensor_temp_sensor_temp_changed(),
        api_current_temp: s.get_temp_sensor_temp_sensor_current_temp(),
      };
      if s.missing() {
        out.report(crate::Event::CheckSkipped { thread: "temp_sensor_temp_sensor", check: "IEP_Post" });
      } else if !crate::gumbox::temp_sensor_temp_sensor_GUMBOX::initialize_IEP_Post(
        post_temp_sensor_temp_sensor.api_temp_changed, post_temp_sensor_temp_sensor.api_current_temp) {
        out.report(crate::Event::IepPostViolation { thread: "temp_sensor_temp_sensor", post: &post_temp_sensor_temp_sensor });
      }
    }
    {
      s.focus(Some(crate::Thread::operator_interface_operator_interface));
      let post_operator_interface_operator_interface = PostState_operator_interface_operator_interface {
        api_desired_temp: s.get_operator_interface_operator_interface_desired_temp(),
      };
      if s.missing() {
        out.report(crate::Event::CheckSkipped { thread: "operator_interface_operator_interface", check: "IEP_Post" });
      } else if !crate::gumbox::operator_interface_operator_interface_GUMBOX::initialize_IEP_Post(
        post_operator_interface_operator_interface.api_desired_temp) {
        out.report(crate::Event::IepPostViolation { thread: "operator_interface_operator_interface", post: &post_operator_interface_operator_interface });
      }
    }
    {
      s.focus(Some(crate::Thread::thermostat_thermostat));
      let post_thermostat_thermostat = PostState_thermostat_thermostat {
        currentSetPoints: s.get_thermostat_thermostat_sv_currentSetPoints(),
        lastCmd: s.get_thermostat_thermostat_sv_lastCmd(),
        api_heat_control: s.get_thermostat_thermostat_heat_control(),
      };
      if s.missing() {
        out.report(crate::Event::CheckSkipped { thread: "thermostat_thermostat", check: "IEP_Post" });
      } else if !crate::gumbox::thermostat_thermostat_GUMBOX::initialize_IEP_Post(
        post_thermostat_thermostat.currentSetPoints, post_thermostat_thermostat.lastCmd, post_thermostat_thermostat.api_heat_control) {
        out.report(crate::Event::IepPostViolation { thread: "thermostat_thermostat", post: &post_thermostat_thermostat });
      }
    }
    {
      s.focus(Some(crate::Thread::heat_source_heat_source));
      let post_heat_source_heat_source = PostState_heat_source_heat_source {
        heater_state: s.get_heat_source_heat_source_sv_heater_state(),
      };
      if s.missing() {
        out.report(crate::Event::CheckSkipped { thread: "heat_source_heat_source", check: "IEP_Post" });
      } else if !crate::gumbox::heat_source_heat_source_GUMBOX::initialize_IEP_Post(
        post_heat_source_heat_source.heater_state) {
        out.report(crate::Event::IepPostViolation { thread: "heat_source_heat_source", post: &post_heat_source_heat_source });
      }
    }
  }

  /// `prev` has completed a dispatch: check its CEP_Post against the pre-state
  /// saved when it was dispatched.
  pub fn on_complete<V: SystemView, S: ViolationSink>(&mut self, prev: crate::Thread, s: &mut V, out: &mut S) {
    match prev {
      crate::Thread::temp_sensor_temp_sensor => {
        s.focus(Some(crate::Thread::temp_sensor_temp_sensor));
        let post = PostState_temp_sensor_temp_sensor {
          api_temp_changed: s.get_temp_sensor_temp_sensor_temp_changed(),
          api_current_temp: s.get_temp_sensor_temp_sensor_current_temp(),
        };
        if s.missing() {
          out.report(crate::Event::CheckSkipped { thread: "temp_sensor_temp_sensor", check: "CEP_Post" });
        } else if let Some(pre) = &self.pre_temp_sensor_temp_sensor {
          if !crate::gumbox::temp_sensor_temp_sensor_GUMBOX::compute_CEP_Post(
            post.api_temp_changed, post.api_current_temp) {
            out.report(crate::Event::CepPostViolation { thread: "temp_sensor_temp_sensor", pre: pre, post: &post });
          }
        } else {
          out.report(crate::Event::CepPostSkipped { thread: "temp_sensor_temp_sensor" });
        }
      }
      crate::Thread::operator_interface_operator_interface => {
        s.focus(Some(crate::Thread::operator_interface_operator_interface));
        let post = PostState_operator_interface_operator_interface {
          api_desired_temp: s.get_operator_interface_operator_interface_desired_temp(),
        };
        if s.missing() {
          out.report(crate::Event::CheckSkipped { thread: "operator_interface_operator_interface", check: "CEP_Post" });
        } else if let Some(pre) = &self.pre_operator_interface_operator_interface {
          if !crate::gumbox::operator_interface_operator_interface_GUMBOX::compute_CEP_Post(
            post.api_desired_temp) {
            out.report(crate::Event::CepPostViolation { thread: "operator_interface_operator_interface", pre: pre, post: &post });
          }
        } else {
          out.report(crate::Event::CepPostSkipped { thread: "operator_interface_operator_interface" });
        }
      }
      crate::Thread::thermostat_thermostat => {
        s.focus(Some(crate::Thread::thermostat_thermostat));
        let post = PostState_thermostat_thermostat {
          currentSetPoints: s.get_thermostat_thermostat_sv_currentSetPoints(),
          lastCmd: s.get_thermostat_thermostat_sv_lastCmd(),
          api_heat_control: s.get_thermostat_thermostat_heat_control(),
        };
        if s.missing() {
          out.report(crate::Event::CheckSkipped { thread: "thermostat_thermostat", check: "CEP_Post" });
        } else if let Some(pre) = &self.pre_thermostat_thermostat {
          if !crate::gumbox::thermostat_thermostat_GUMBOX::compute_CEP_Post(
            pre.In_currentSetPoints, pre.In_lastCmd, post.currentSetPoints, post.lastCmd, pre.api_temp_changed, pre.api_desired_temp, pre.api_current_temp, post.api_heat_control) {
            out.report(crate::Event::CepPostViolation { thread: "thermostat_thermostat", pre: pre, post: &post });
          }
        } else {
          out.report(crate::Event::CepPostSkipped { thread: "thermostat_thermostat" });
        }
      }
      crate::Thread::heat_source_heat_source => {
        s.focus(Some(crate::Thread::heat_source_heat_source));
        let post = PostState_heat_source_heat_source {
          heater_state: s.get_heat_source_heat_source_sv_heater_state(),
        };
        if s.missing() {
          out.report(crate::Event::CheckSkipped { thread: "heat_source_heat_source", check: "CEP_Post" });
        } else if let Some(pre) = &self.pre_heat_source_heat_source {
          if !crate::gumbox::heat_source_heat_source_GUMBOX::compute_CEP_Post(
            pre.In_heater_state, post.heater_state, pre.api_heat_control) {
            out.report(crate::Event::CepPostViolation { thread: "heat_source_heat_source", pre: pre, post: &post });
          }
        } else {
          out.report(crate::Event::CepPostSkipped { thread: "heat_source_heat_source" });
        }
      }
    }
  }

  /// Drops every saved pre-state, so each thread's next completion is skipped rather
  /// than checked against a dispatch it no longer describes -- after a dispatch went
  /// unobserved, or a thread overran its slot.
  pub fn forget(&mut self) {
    self.pre_temp_sensor_temp_sensor = None;
    self.pre_operator_interface_operator_interface = None;
    self.pre_thermostat_thermostat = None;
    self.pre_heat_source_heat_source = None;
  }

  /// `next` is about to be dispatched: save its pre-state and check its CEP_Pre.
  pub fn on_dispatch<V: SystemView, S: ViolationSink>(&mut self, next: crate::Thread, s: &mut V, out: &mut S) {
    match next {
      crate::Thread::temp_sensor_temp_sensor => {
        s.focus(Some(crate::Thread::temp_sensor_temp_sensor));
        let pre = PreState_temp_sensor_temp_sensor {
        };
        if s.missing() {
          // no pre-state to hold the completion to, and no CEP_Pre that failed
          out.report(crate::Event::CheckSkipped { thread: "temp_sensor_temp_sensor", check: "CEP_Pre" });
          self.pre_temp_sensor_temp_sensor = None;
          self.pre_ok_temp_sensor_temp_sensor = true;
        } else {
          self.pre_ok_temp_sensor_temp_sensor = true;
          self.pre_temp_sensor_temp_sensor = Some(pre);
        }
      }
      crate::Thread::operator_interface_operator_interface => {
        s.focus(Some(crate::Thread::operator_interface_operator_interface));
        let pre = PreState_operator_interface_operator_interface {
        };
        if s.missing() {
          // no pre-state to hold the completion to, and no CEP_Pre that failed
          out.report(crate::Event::CheckSkipped { thread: "operator_interface_operator_interface", check: "CEP_Pre" });
          self.pre_operator_interface_operator_interface = None;
          self.pre_ok_operator_interface_operator_interface = true;
        } else {
          self.pre_ok_operator_interface_operator_interface = true;
          self.pre_operator_interface_operator_interface = Some(pre);
        }
      }
      crate::Thread::thermostat_thermostat => {
        s.focus(Some(crate::Thread::thermostat_thermostat));
        let pre = PreState_thermostat_thermostat {
          In_currentSetPoints: s.get_thermostat_thermostat_sv_currentSetPoints(),
          In_lastCmd: s.get_thermostat_thermostat_sv_lastCmd(),
          api_temp_changed: s.get_temp_sensor_temp_sensor_temp_changed(),
          api_desired_temp: s.get_operator_interface_operator_interface_desired_temp(),
          api_current_temp: s.get_temp_sensor_temp_sensor_current_temp(),
        };
        if s.missing() {
          // no pre-state to hold the completion to, and no CEP_Pre that failed
          out.report(crate::Event::CheckSkipped { thread: "thermostat_thermostat", check: "CEP_Pre" });
          self.pre_thermostat_thermostat = None;
          self.pre_ok_thermostat_thermostat = true;
        } else {
          if !crate::gumbox::thermostat_thermostat_GUMBOX::compute_CEP_Pre(
            pre.In_currentSetPoints, pre.In_lastCmd, pre.api_temp_changed, pre.api_desired_temp, pre.api_current_temp) {
            out.report(crate::Event::CepPreViolation { thread: "thermostat_thermostat", pre: &pre });
            self.pre_ok_thermostat_thermostat = false;
          } else {
            self.pre_ok_thermostat_thermostat = true;
          }
          self.pre_thermostat_thermostat = Some(pre);
        }
      }
      crate::Thread::heat_source_heat_source => {
        s.focus(Some(crate::Thread::heat_source_heat_source));
        let pre = PreState_heat_source_heat_source {
          In_heater_state: s.get_heat_source_heat_source_sv_heater_state(),
          api_heat_control: s.get_thermostat_thermostat_heat_control(),
        };
        if s.missing() {
          // no pre-state to hold the completion to, and no CEP_Pre that failed
          out.report(crate::Event::CheckSkipped { thread: "heat_source_heat_source", check: "CEP_Pre" });
          self.pre_heat_source_heat_source = None;
          self.pre_ok_heat_source_heat_source = true;
        } else {
          self.pre_ok_heat_source_heat_source = true;
          self.pre_heat_source_heat_source = Some(pre);
        }
      }
    }
  }

  /// Whether `t`'s CEP_Pre failed at its latest dispatch check -- the sender did not
  /// meet `t`'s contract.  A host that rejects such a dispatch (the test controller)
  /// asks this after `on_dispatch`.
  pub fn pre_failed(&self, t: crate::Thread) -> bool {
    match t {
      crate::Thread::temp_sensor_temp_sensor => !self.pre_ok_temp_sensor_temp_sensor,
      crate::Thread::operator_interface_operator_interface => !self.pre_ok_operator_interface_operator_interface,
      crate::Thread::thermostat_thermostat => !self.pre_ok_thermostat_thermostat,
      crate::Thread::heat_source_heat_source => !self.pre_ok_heat_source_heat_source,
    }
  }
}
